items=DATA["items"];cats=DATA["cats"]
def make_page(item,image):
    esc=html.escape
    cat=item['category'];title=esc(item['title']);description=esc(item['description']);label=cats[cat]
    if cat in ('resin','voetbal'): finishes=['Volledig handgeschilderd']
    elif cat=='bloemenvazen': finishes=['Kant-en-klaar afgewerkt']
    elif cat=='laser': finishes=['Natuurlijk hout met gravure','Geschilderde afwerking op aanvraag']
    else: finishes=['Wit / onbeschilderd','Eén gewenste kleur','Volledig handgeschilderd']
    finish=''.join('<option>'+esc(x)+'</option>' for x in finishes)
    notes='Alleen 3D-printmateriaal en optionele verf; geen extra onderdelen inbegrepen.'
    if cat=='laser':notes='Laserbewerkt berkenmultiplex. Verbindingen en gravure worden vooraf technisch uitgewerkt; geen beslag inbegrepen.'
    if cat=='bloemenvazen':notes='Decoratieve droogbloemvaas, zonder bloemen of glazen inzetstuk. Waterdichtheid wordt niet beloofd.'
    if cat=='maskers':notes='Decoratief masker zonder banden of bevestigingsmateriaal. Geen beschermingsmasker. Pasvorm wordt vooraf besproken.'
    return f'''<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#242b38"><title>{title} | Makers 3D Labs</title><meta name="description" content="{description}"><link rel="stylesheet" href="assets/shop.css"><link rel="stylesheet" href="assets/nieuwe-producten-100.css?v=1"><link rel="stylesheet" href="assets/bovenmenu.css?v=2"></head><body class="mk-new-product"><!-- makers-new100-product --><header><a href="index.html">Makers 3D Labs — Home</a></header><main class="np-main"><a href="categorie-{cat}.html">← Terug naar {label}</a><div class="np-layout"><figure class="np-figure"><img src="{esc(image)}" alt="Digitaal ontwerpvoorbeeld van {title}" width="1254" height="1254" fetchpriority="high"><figcaption>Digitaal ontwerpvoorbeeld. Formaat, maakbaarheid en definitieve uitvoering worden vóór bestelling bevestigd. De voorbeeldfoto verandert niet mee met je keuzes.</figcaption></figure><div><span class="np-kicker">{label} · op bestelling</span><h1>{title}</h1><p>{description}</p><p class="np-price">Prijs op aanvraag</p><p class="np-request-note">De prijs is nog niet vastgesteld. Stuur jouw wensen door; je ontvangt eerst een voorstel met uitvoering, prijs en levertijd. Deze aanvraag is nog geen bestelling en je betaalt hier niets.</p><form class="np-form" action="https://formsubmit.co/alejandrojenniferbruna@gmail.com" method="POST" enctype="multipart/form-data"><h2>Stel jouw uitvoering samen</h2><input type="hidden" name="Product" value="{title}"><input type="hidden" name="Categorie" value="{label}"><input type="hidden" name="Prijsstatus" value="Prijs op aanvraag — nog geen bestelling"><input type="hidden" name="_subject" value="Productaanvraag — {title}"><input type="hidden" name="_captcha" value="true"><input class="np-trap" type="text" name="_honey" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="np-fields"><div class="np-field"><label for="formaat">Formaat *</label><select id="formaat" name="Formaat" required><option value="">Kies een formaat</option><option>Klein — maat in overleg</option><option>Middel — maat in overleg</option><option>Groot — maat in overleg</option><option>Eigen maat — hieronder toelichten</option></select></div><div class="np-field"><label for="uitvoering">Uitvoering *</label><select id="uitvoering" name="Uitvoering" required>{finish}</select></div><div class="np-field np-full"><label for="kleur">Gewenste kleur(en)</label><input id="kleur" name="Gewenste kleuren" maxlength="180" placeholder="Alle kleuren zijn aan te vragen; wij bevestigen de uitvoering"></div><div class="np-field"><label for="aantal">Aantal *</label><input id="aantal" name="Aantal" type="number" min="1" max="10000" step="1" value="1" required></div><div class="np-field"><label for="datum">Gewenste leverdatum</label><input id="datum" name="Gewenste leverdatum" type="date"></div><div class="np-field np-full"><label for="personalisatie">Naam, tekst, maat of andere wensen</label><textarea id="personalisatie" name="Personalisatiewensen" maxlength="3000" placeholder="Bijvoorbeeld een naam, rugnummer, kleurverdeling of gewenste afmetingen. Laat leeg als je geen extra wensen hebt."></textarea></div><div class="np-field np-full"><label for="fotos">Afbeeldingen of een schets toevoegen</label><div class="np-upload"><input id="fotos" name="fotos" type="file" accept="image/jpeg,image/png,image/webp" multiple aria-describedby="np-file-hint np-file-error"><p class="np-hint" id="np-file-hint">Optioneel · maximaal 5 JPG-, PNG- of WebP-afbeeldingen · samen maximaal 9 MB.</p><div class="np-preview" aria-live="polite"></div><div class="np-error" id="np-file-error" role="alert"></div></div></div><div class="np-field"><label for="naam">Jouw naam *</label><input id="naam" name="naam" autocomplete="name" maxlength="120" required></div><div class="np-field"><label for="email">E-mailadres *</label><input id="email" name="email" type="email" autocomplete="email" maxlength="180" required></div></div><div class="np-check"><input id="akkoord" name="Toestemming" value="Ja" type="checkbox" required><label for="akkoord">Ik geef toestemming om mijn gegevens en eventuele afbeeldingen via FormSubmit te versturen voor het behandelen van mijn aanvraag. <a href="informatie.html">Informatie &amp; voorwaarden</a>.</label></div><button class="np-submit" type="submit">Vraag een prijsvoorstel aan →</button><p class="np-hint">Je ontvangt eerst een voorstel. Een gewenste leverdatum is nog geen bevestigde levertijd.</p></form><details class="np-details"><summary>Uitvoering en materiaal</summary><p>{notes} De afbeelding dient ter inspiratie; details kunnen bij het technisch uitwerken veranderen. Verwerking van het aanvraagformulier vereist activering van de bestaande formulierdienst.</p></details></div></div></main><script src="assets/shop-data.js"></script><script src="assets/shop.js"></script><script src="assets/nieuwe-producten-100.js?v=1"></script><script src="assets/bovenmenu.js?v=2"></script></body></html>'''

def eur(cents):return "€ "+f"{cents/100:.2f}".replace(".",",")
def zodiac_page(item,image):
    esc=html.escape;cat=item['category']
    page=make_page(item,image)
    page=page.replace('<!-- makers-new100-product -->','<!-- makers-zodiac-krijgers-product -->')
    page=page.replace('assets/nieuwe-producten-100.css?v=1','assets/sterrenbeeld-krijgers.css?v=1').replace('assets/nieuwe-producten-100.js?v=1','assets/sterrenbeeld-krijgers.js?v=1')
    page=page.replace('<p class="np-price">Prijs op aanvraag</p>','<p class="np-price">Vanaf '+eur(item['start_price'])+'</p>')
    page=page.replace('De prijs is nog niet vastgesteld. Stuur jouw wensen door; je ontvangt eerst een voorstel met uitvoering, prijs en levertijd. Deze aanvraag is nog geen bestelling en je betaalt hier niets.','Prijzen inclusief btw, exclusief verzending. Kies jouw uitvoering en bekijk het bedrag hieronder. Je ontvangt eerst een bevestiging van maakbaarheid, uitvoering en levertijd. Je betaalt hier nog niets.')
    page=page.replace('Prijs op aanvraag — nog geen bestelling','Prijsvoorstel — nog geen bestelling')
    options=''.join('<option value="'+str(n)+'" data-price="'+str(p)+'">'+esc(label)+' — '+eur(p)+'</option>' for n,(label,p) in enumerate(zip(item['labels'],item['prices'])))
    options+='<option value="custom" data-price="">Afwijkende maat of uitvoering — prijs op aanvraag</option>'
    control='<select id="np-variant" name="Gekozen variant" required>'+options+'</select>'
    if cat=='maskers':
        page=re.sub(r'<select id="uitvoering"[\s\S]*?</select>',control,page,count=1)
        page=page.replace('for="uitvoering"','for="np-variant"')
        page=re.sub(r'<select id="formaat"[\s\S]*?</select>','<select id="formaat" name="Formaat" required><option value="Standaard — circa 22 tot 25 cm hoog, modelafhankelijk">Standaard — circa 22 tot 25 cm hoog</option><option value="Eigen maat — prijs op aanvraag">Eigen maat — prijs op aanvraag</option></select>',page,count=1)
        extra='<div class="np-check"><input type="checkbox" id="np-extra" name="Extra personalisatie" value="Naam of korte tekst — 14,95 euro extra"><label for="np-extra">Naam of korte tekst toevoegen: +€ 14,95. Beschrijf hieronder jouw wensen.</label></div>'
        page=page.replace('<div class="np-fields">',extra+'<div class="np-fields">',1)
        page=page.replace('<label for="personalisatie">Naam, tekst, maat of andere wensen</label>','<label for="personalisatie">Personalisatiewensen of afwijkende maat</label>')
    else:
        page=re.sub(r'<select id="formaat"[\s\S]*?</select>',control,page,count=1).replace('for="formaat"','for="np-variant"')
        if cat=='persoonlijk':
            page=re.sub(r'<select id="uitvoering"[\s\S]*?</select>','<select id="uitvoering" name="Uitvoering"><option>Kant-en-klaar handgeschilderd</option></select>',page,count=1)
            name='<div class="np-field np-full"><label for="np-personal-name">Gewenste naam, initiaal of korte tekst *</label><input id="np-personal-name" name="Persoonlijke naam of tekst" maxlength="40" required placeholder="Bijvoorbeeld Emma of de letter E"><p class="np-hint">Eén naam, initiaal of korte tekst is inbegrepen.</p></div>'
            page=page.replace('<div class="np-fields">','<div class="np-fields">'+name,1)
    totals='<div class="np-totals" aria-live="polite"><p>Per stuk: <strong id="np-unit">'+eur(item['start_price'])+'</strong></p><p>Totaal: <strong id="np-total">'+eur(item['start_price'])+'</strong></p><p class="np-hint">Inclusief btw · exclusief verzending · extra maatwerk wordt vooraf geoffreerd.</p></div><input type="hidden" name="Uitvoering en maat" id="np-label-hidden"><input type="hidden" name="Stukprijs" id="np-unit-hidden"><input type="hidden" name="Totaalprijs" id="np-total-hidden">'
    page=page.replace('<div class="np-check"><input id="akkoord"',totals+'<div class="np-check"><input id="akkoord"',1)
    page=page.replace('Vraag een prijsvoorstel aan →','Vraag deze uitvoering aan →')
    page=page.replace('Makers 3D Labs</title>','Makers 3D Labs</title>',1)
    return page

if not (ROOT/'index.html').is_file() or not (ROOT/'assets/shop.js').is_file():
    raise SystemExit('Voer dit uit in /workspaces/makers-3d-labs.')
all_images={}
for p in ROOT.rglob('*.webp'):
    if '.git' not in p.relative_to(ROOT).parts: all_images.setdefault(p.name,[]).append(p)
resolved={};missing=[]
for item in items:
    options=all_images.get(item['image_filename'],[])
    if not options:missing.append(item['image_filename']);continue
    if len(options)>1 and len({hashlib.sha256(p.read_bytes()).hexdigest() for p in options})>1:
        raise SystemExit('Meerdere verschillende versies gevonden van '+item['image_filename']+'. Houd eerst één versie over.')
    path=min(options,key=lambda p:(len(p.relative_to(ROOT).parts),str(p)))
    resolved[item['id']]=quote(path.relative_to(ROOT).as_posix(),safe='/')
if missing:
    raise SystemExit('Nog geen bestanden aangepast. Deze afbeeldingen ontbreken ('+str(len(missing))+'):\n'+'\n'.join(missing)+'\nPak de ZIP uit, upload de WebP-bestanden en klik Commit changes in GitHub. Voer daarna git pull uit en probeer opnieuw.')
changes={};counts={}
for cat,label in cats.items():
    path=ROOT/('categorie-'+cat+'.html')
    if not path.is_file():raise SystemExit('Categorie ontbreekt: '+path.name+'; niets aangepast.')
    content=path.read_text(encoding='utf-8')
    content=re.sub(r'<article\b[^>]*id="malezodiac12-[0-9]{2}"[^>]*>[\s\S]*?</article>','',content)
    additions=[]
    for item in [x for x in items if x['category']==cat]:
        esc=html.escape;image=resolved[item['id']]
        colors=['Wit','Meerkleurig','Op aanvraag'] if cat=='maskers' else ['Meerkleurig','Op aanvraag']
        color_attr=esc(json.dumps(colors,ensure_ascii=False),quote=True)
        card=f'<article id="malezodiac12-{item["id"]}" class="category-product" data-name="{esc(item["title"])}" data-colors="{color_attr}" data-kind="{esc(item["kind"])}" data-zodiac="{esc(item["sign"])}" data-price="{item["start_price"]}" data-personal="true"><a class="category-product-photo" href="{item["page"]}"><img src="{esc(image)}" alt="{esc(item["title"])} — digitaal ontwerpvoorbeeld" width="1254" height="1254" loading="lazy"></a><div class="category-product-body"><span class="category-product-type">{label} · krijgersreeks</span><h2>{esc(item["title"])}</h2><p>{esc(item["description"])}</p><strong class="category-price">Vanaf {eur(item["start_price"])}</strong><a class="category-product-link" href="{item["page"]}">Kies jouw uitvoering →</a></div></article>'
        additions.append(card)
        target=ROOT/item['page']
        if target.exists() and 'makers-zodiac-krijgers-product' not in target.read_text(encoding='utf-8'):
            raise SystemExit('Bestaande pagina niet overschreven: '+target.name)
        changes[target]=zodiac_page(item,image)
    content,n=re.subn(r'(<div\b[^>]*id="category-products"[^>]*>)',lambda m:m.group(1)+''.join(additions),content,count=1)
    if n!=1:raise SystemExit('Productoverzicht niet gevonden in '+path.name+'; niets aangepast.')
    if 'name="zodiac"' not in content:
        content=content.replace('</form>','<fieldset class="filter-group"><legend>Sterrenbeeld</legend><label class="filter-check"><input type="checkbox" name="zodiac" value="__placeholder__"><span hidden>Placeholder</span></label></fieldset></form>',1)
    required={'kind':sorted({x['kind'] for x in items if x['category']==cat}),'color':['Wit','Meerkleurig','Op aanvraag'] if cat=='maskers' else ['Meerkleurig','Op aanvraag'],'zodiac':[x['sign'] for x in items if x['category']==cat]}
    for name,values in required.items():
        for value in values:
            if re.search(r'name="'+name+r'"[^>]*value="'+re.escape(value)+r'"',content):continue
            field=re.search(r'<fieldset\b[^>]*>[\s\S]*?name="'+name+r'"[\s\S]*?</fieldset>',content)
            if not field:raise SystemExit('Filter '+name+' ontbreekt in '+path.name+'; niets aangepast.')
            end=field.end()-len('</fieldset>')
            option='<label class="filter-check"><input type="checkbox" name="'+name+'" value="'+html.escape(value)+'"><span>'+html.escape(value)+'</span></label>'
            content=content[:end]+option+content[end:]
    content=re.sub(r'<label class="filter-check"><input type="checkbox" name="zodiac" value="__placeholder__"><span hidden>Placeholder</span></label>','',content)
    content=re.sub(r'<script id="sterrenbeelden-filter">[\s\S]*?</script>','',content)
    content=content.replace('</body>',DATA['filter_script']+'</body>',1)
    changes[path]=content;counts[cat]=len(additions)
filter_path=ROOT/'assets/categorie-paginas.js'
if not filter_path.is_file():raise SystemExit('Categoriefilters ontbreken; niets aangepast.')
filter_source=filter_path.read_text(encoding='utf-8')
needle="let show=!invalid&&"
if "checked('zodiac')" not in filter_source:
    if needle not in filter_source:raise SystemExit('Categoriefilters zijn gewijzigd; niets aangepast.')
    filter_source=filter_source.replace(needle,"let show=(!checked('zodiac').length||checked('zodiac').includes(item.el.dataset.zodiac))&&!invalid&&",1)
changes[filter_path]=filter_source
changes[ROOT/'assets/sterrenbeeld-krijgers.css']=DATA['css']
changes[ROOT/'assets/sterrenbeeld-krijgers.js']=DATA['js']
for path,content in changes.items():
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(content,encoding='utf-8')
stage=[str(p.relative_to(ROOT).as_posix()) for p in changes]
(ROOT/'sterrenbeeld-krijgers-bestanden.txt').write_text('\n'.join(stage)+'\n',encoding='utf-8')
print('Klaar: 12 sterrenbeeld-krijgersmaskers in categorie Maskers en aanvraagformulieren toegevoegd.')
for cat,count in counts.items():print(cats[cat]+': '+str(count)+' nieuwe producten')
print('Prijzen en varianten ingesteld. Nog niet gepubliceerd.')
